package com.rpb.reservation.workforce.compliance;
import static com.rpb.reservation.workforce.compliance.ComplianceDtos.*;
import com.rpb.reservation.workforce.application.*;import com.rpb.reservation.workforce.persistence.WorkforceEmployeeRepository;
import com.rpb.reservation.workforce.domain.WorkforceException;import com.rpb.reservation.walkin.api.CurrentActor;
import java.time.*;import java.net.URI;import java.util.*;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true) public class ComplianceService {
 private final WorkforceAccess gate;private final ComplianceAccess access;private final ComplianceRepository repo;private final WorkforceEmployeeRepository employees;private final WorkforceAudit audit;private final Clock clock;
 public ComplianceService(WorkforceAccess gate,ComplianceAccess access,ComplianceRepository repo,WorkforceEmployeeRepository employees,WorkforceAudit audit,Clock clock){this.gate=gate;this.access=access;this.repo=repo;this.employees=employees;this.audit=audit;this.clock=clock;}
 public Reference reference(CurrentActor a,UUID store){access.headquarters(a,store);return ComplianceReference.singapore();}
 public List<Policy> policies(CurrentActor a,UUID store){access.headquarters(a,store);return repo.policies(a.tenantId());}
 public List<Policy> versions(CurrentActor a,UUID store,UUID id){access.headquarters(a,store);return repo.versions(a.tenantId(),id);}
 @Transactional public Policy savePolicy(CurrentActor a,UUID store,UUID id,PolicyWrite c){
  gate.sourceWrite(a);access.headquarters(a,store);if(id==null||c==null||c.expectedVersion()==null||c.expectedVersion()<0||c.name()==null||c.name().isBlank()||c.name().length()>100||c.effectiveFrom()==null||c.effectiveTo()==null||c.effectiveTo().isBefore(c.effectiveFrom())||c.publish()==null||c.sources()==null||c.sources().isEmpty()||c.sources().size()>30)throw WorkforceException.invalid();ComplianceRules.validate(c.rules());
  for(var s:c.sources()){if(s==null||s.code()==null||s.code().isBlank()||s.code().length()>80||s.title()==null||s.title().isBlank()||s.title().length()>200||s.summary()==null||s.summary().isBlank()||s.summary().length()>3000||s.url()==null||s.url().length()>2048||s.checkedOn()==null||s.checkedOn().isAfter(LocalDate.now(clock.withZone(ZoneId.of("Asia/Singapore")))))throw WorkforceException.invalid();try{var uri=URI.create(s.url());if(!"https".equals(uri.getScheme())||uri.getHost()==null||!uri.getHost().endsWith(".gov.sg")||uri.getUserInfo()!=null)throw WorkforceException.invalid();}catch(IllegalArgumentException ex){throw WorkforceException.invalid();}}
  if(c.sources().stream().map(Source::code).distinct().count()!=c.sources().size())throw WorkforceException.invalid();repo.lock(a.tenantId(),"policy:"+id);var all=repo.versions(a.tenantId(),id);var old=all.isEmpty()?null:all.getFirst();
  var next=new Policy(id,c.expectedVersion()+1,c.name().trim(),c.effectiveFrom(),c.effectiveTo(),c.publish()?"published":"draft",c.rules(),List.copyOf(c.sources()),c.publish()?a.actorId():null);
  if(old!=null&&old.version()==next.version()&&old.equals(next))return old;if((old==null?0:old.version())!=c.expectedVersion())throw WorkforceException.conflict();repo.policy(a,next);audit.changed(a,store,"compliance-policy.save",id,old,next);return next;
 }
 public ContractPage contracts(CurrentActor a,UUID store,UUID employee){var e=access.employee(a,store,employee,false);var list=repo.contracts(a.tenantId(),employee);var policies=new LinkedHashMap<String,Policy>();for(var c:list)repo.policy(a.tenantId(),c.policyId(),c.policyVersion()).ifPresent(p->policies.put(p.id()+":"+p.version(),p));boolean manage=gate.managedStores(a).containsAll(e.storeIds());if(manage)for(var p:repo.publishedPolicies(a.tenantId()))policies.put(p.id()+":"+p.version(),p);return new ContractPage(e.id(),e.name(),manage,list.stream().filter(c->c.companyId().equals(e.companyId())).toList(),List.copyOf(policies.values()),e.companyId(),e.companyEffectiveDate()==null?e.hireDate():e.companyEffectiveDate(),list.isEmpty()?0:list.getLast().version());}
 @Transactional public Contract saveContract(CurrentActor a,UUID store,UUID employee,UUID id,ContractWrite c){
  gate.sourceWrite(a);access.employee(a,store,employee,true);if(id==null||c==null||c.expectedVersion()==null||c.expectedVersion()<0||c.effectiveFrom()==null||c.serviceStart()==null||c.serviceStart().isAfter(c.effectiveFrom())||c.policyId()==null||c.policyVersion()==null||c.policyVersion()<1||!ComplianceRules.positive(c.dailyHours())||!ComplianceRules.positive(c.weeklyHours())||!ComplianceRules.positive(c.weeklyDays())||c.weeklyDays().compareTo(new java.math.BigDecimal("7"))>0||!ComplianceRules.positive(c.comparableDailyHours())||!ComplianceRules.positive(c.comparableWeeklyHours())||c.category()==null||!Set.of("workman","non_workman","manager").contains(c.category())||c.evidence()==null||c.evidence().isBlank()||c.evidence().length()>1000)throw WorkforceException.invalid();
  employees.lock(employee);var e=access.employee(a,store,employee,true);access.notSelf(a,e);repo.lock(a.tenantId(),"contract:"+employee);var replay=repo.replay(a,store,id,"contract:"+employee,c,Contract.class);if(replay.isPresent())return replay.get();var p=repo.policy(a.tenantId(),c.policyId(),c.policyVersion()).orElseThrow(WorkforceException::missing);if(!p.status().equals("published")||c.effectiveFrom().isBefore(p.effectiveFrom())||c.effectiveFrom().isAfter(p.effectiveTo())||c.serviceStart().isBefore(e.hireDate()))throw WorkforceException.invalid();var all=repo.contracts(a.tenantId(),employee);var old=all.isEmpty()?null:all.getLast();if((old==null?0:old.version())!=c.expectedVersion()||old!=null&&!c.effectiveFrom().isAfter(old.effectiveFrom()))throw WorkforceException.conflict();
  if(c.dailyHours().compareTo(java.math.BigDecimal.valueOf(p.rules().maxDailyHours()))>0||c.weeklyHours().compareTo(p.rules().normalWeekHours())>0||c.comparableWeeklyHours().compareTo(p.rules().normalWeekHours())>0||c.dailyHours().compareTo(c.comparableDailyHours())>0||c.weeklyHours().compareTo(c.comparableWeeklyHours())>0||c.weeklyHours().compareTo(c.dailyHours().multiply(c.weeklyDays()))>0)throw WorkforceException.invalid();
  var normalDaily=c.weeklyDays().compareTo(java.math.BigDecimal.valueOf(p.rules().shortWeekMaxDays()))<=0?p.rules().shortWeekDailyHours():p.rules().longWeekDailyHours();if(c.dailyHours().compareTo(normalDaily)>0)throw new WorkforceException("COMPLIANCE_SPECIAL_ARRANGEMENT_REQUIRED",409);
  var next=new Contract(id,employee,e.companyId(),c.expectedVersion()+1,c.effectiveFrom(),c.serviceStart(),p.id(),p.version(),c.dailyHours(),c.weeklyHours(),c.weeklyDays(),c.comparableDailyHours(),c.comparableWeeklyHours(),c.category(),c.evidence().trim(),ComplianceRules.partTime(p.rules(),c.weeklyHours()));repo.contract(a,next);repo.receipt(a,store,id,"contract:"+employee,c,next);audit.changed(a,store,"employment-contract.save",id,old,next);return next;
 }
}
